<!-- ================= FEATURES ================= -->
<section class="section" id="journey" aria-labelledby="journey-title">
  <div class="wrap">
    <div class="section-head">
      <div>
        <span class="eyebrow">The journey</span>
        <h2 id="journey-title">Built for the slow way <em>across.</em></h2>
      </div>
      <p>Eleven hours, one long horizon. We run quiet electric trains on a single desert line, timed so the dunes are golden as you board and the city is glowing as you wake.</p>
    </div>

    <div class="features">
      <article class="card">
        <div class="card-top">
          <div class="icon">
            <svg width="30" height="30" viewBox="0 0 30 30" fill="none" aria-hidden="true">
              <rect x="4" y="4" width="22" height="22" rx="4" stroke="#ecc98f" stroke-width="1.5"/>
              <path d="M4 12h22" stroke="#ecc98f" stroke-opacity=".45" stroke-width="1.2"/>
              <path d="M19.5 15.5a4.5 4.5 0 1 1-4.6-5 3.6 3.6 0 0 0 4.6 5Z" fill="#ff4fa3" fill-opacity=".9"/>
              <circle cx="9" cy="8" r=".9" fill="#ecc98f"/><circle cx="21" cy="21" r=".9" fill="#ecc98f"/>
            </svg>
          </div>
          <span class="num">01</span>
        </div>
        <h3>Skylight sleepers</h3>
        <p>Every berth has a roof window tilted to the southern sky. Cabin lights dim at 23:00, and the Milky Way does the rest.</p>
        <div class="detail">Blackout blinds · Desert-linen bedding</div>
      </article>

      <article class="card">
        <div class="card-top">
          <div class="icon">
            <svg width="30" height="30" viewBox="0 0 30 30" fill="none" aria-hidden="true">
              <path d="M5 15h20a10 10 0 0 1-20 0Z" stroke="#ecc98f" stroke-width="1.5" stroke-linejoin="round"/>
              <path d="M3 25h24" stroke="#ecc98f" stroke-width="1.5" stroke-linecap="round"/>
              <path d="M11 11c-1.2-1.4 1.2-2.6 0-4M15 11c-1.2-1.4 1.2-2.6 0-4M19 11c-1.2-1.4 1.2-2.6 0-4" stroke="#ff4fa3" stroke-width="1.4" stroke-linecap="round"/>
            </svg>
          </div>
          <span class="num">02</span>
        </div>
        <h3>The Oasis dining car</h3>
        <p>Supper of dates, saffron and slow smoke, cooked on board and served as the train crests the great dunes at Qasr Ridge.</p>
        <div class="detail">Served 20:30 – 23:00 · Bar till late</div>
      </article>

      <article class="card">
        <div class="card-top">
          <div class="icon">
            <svg width="30" height="30" viewBox="0 0 30 30" fill="none" aria-hidden="true">
              <path d="M8 20a7 7 0 0 1 14 0" stroke="#ff4fa3" stroke-width="1.5" stroke-linecap="round"/>
              <path d="M15 6v3M6.5 10.5l2 2M23.5 10.5l-2 2M3 17h2.5M24.5 17H27" stroke="#ecc98f" stroke-width="1.5" stroke-linecap="round"/>
              <path d="M3 20h24M7 24h16" stroke="#ecc98f" stroke-width="1.5" stroke-linecap="round"/>
            </svg>
          </div>
          <span class="num">03</span>
        </div>
        <h3>Arrive at first light</h3>
        <p>Roll into Lumora as the neon fades into sunrise. Hot shower, strong coffee, and your luggage waiting on the platform.</p>
        <div class="detail">Arrival 06:40 · Lumora Central</div>
      </article>
    </div>

    <div class="journey" aria-label="Route overview">
      <div class="journey-title">
        <span class="eyebrow">Route · DL 203</span>
        <h3>Port Ochre to Lumora</h3>
      </div>
      <div class="stops">
        <div class="stop"><span class="stop-time">19:40</span><span class="stop-name">Port Ochre</span><span class="stop-note">Board at golden hour</span></div>
        <div class="stop"><span class="stop-time">22:15</span><span class="stop-name">Kharim Oasis</span><span class="stop-note">Ten-minute palm stop</span></div>
        <div class="stop"><span class="stop-time">01:30</span><span class="stop-name">Qasr Ridge</span><span class="stop-note">Highest dune on the line</span></div>
        <div class="stop"><span class="stop-time">06:40</span><span class="stop-name">Lumora</span><span class="stop-note">The neon city at dawn</span></div>
      </div>
    </div>
  </div>
</section>

<!-- ================= TIMETABLE ================= -->
<section class="section timetable" id="timetable" aria-labelledby="tt-title">
  <div class="wrap">
    <div class="section-head">
      <div>
        <span class="eyebrow">Timetable</span>
        <h2 id="tt-title">Four departures, <em>every one at dusk.</em></h2>
      </div>
      <p>All services leave Port Ochre between sunset and the last light. Choose your night; we’ll hold your berth for 20 minutes while you decide.</p>
    </div>

    <div class="tt">
      <div class="tt-head">
